import * as G from './engine.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,cls='',disabled=false)=>`<button data-action="${esc(action)}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`;
const safe=s=>!s.fight&&!s.delve;
function rewardText(reward){return [`${reward.xp} XP`,`${reward.coins} coins`,...Object.entries(reward.materials||{}).map(([m,n])=>`${n} ${m}`)].join(' · ');}
function objectives(contract){return `<ul class="story-objectives">${contract.objectives.map(o=>`<li class="${o.done?'done':''}"><span>${o.done?'✓':'○'} ${esc(o.label)}</span><strong>${o.current} / ${o.target}</strong></li>`).join('')}</ul>`;}
function contractCard(s,c){
 const actions=c.ready?`<div class="story-buttons">${button(`story-claim:${c.id}:coins`,'Report to Mara · collect reward','primary',!safe(s))}${c.id==='drainage_inspection'?button(`story-claim:${c.id}:materials`,'Help repairs · 10 coins + 3 fittings','subtle',!safe(s)):''}</div>`:c.available?button('story-accept:'+c.id,'Accept this '+c.kind+' contract','primary',!safe(s)):'';
 const hunts=c.active&&!c.ready?[...new Set(G.STORY_CONTRACTS[c.id].objectives.filter(o=>o.source==='victories').map(o=>o.enemy))].filter(id=>id!=='boss').map(id=>{const e=G.ENEMIES.find(v=>v.id===id);return button('hunt:'+id,`Hunt ${esc(e.name)} →`,'subtle',!!s.fight||!!s.delve||e.level>s.level+2||s.hp<=0);}).join(''):'';
 return `<article class="panel story-contract ${c.kind}"><div class="panel-label"><span>${c.kind==='major'?'MAJOR STORY MILESTONE':'MINOR CONTRACT'}</span><span>${c.ready?'READY TO REPORT':c.active?'IN PROGRESS':'AVAILABLE'}</span></div><h3>${esc(c.title)}</h3><p class="story-employer">${esc(c.employer)} · ${esc(c.chapter)}</p><p>${esc(c.text)}</p>${objectives(c)}<div class="story-reward">Reward: ${esc(rewardText(c.reward))}</div>${c.available?'<p class="story-hint">Progress counts after you accept. Completed hunts pay their own rewards as well.</p>':''}${actions}${hunts?`<div class="story-buttons">${hunts}</div>`:''}${c.id==='municipal_works'&&c.active?button('story-delve','Prepare a descent →','subtle',!safe(s)):''}</article>`;
}
export function renderStorySummary(s){
 const story=G.storyState(s),active=story.active,next=active.find(c=>c.kind==='major')||active[0]||story.available[0]||story.nextMajor;
 return `<section class="panel quest-panel"><div class="panel-label">YOUR STORY · ${story.majorCompleted} / ${story.majorTotal} MILESTONES</div><h3>${esc(next?.title||story.title)}</h3><p>${esc(next?.text||'Meet Mara at the lower stair. Learn why the canal crews have stopped reporting for work.')}</p>${next?.active?objectives(next):`<div class="quest-goal">${esc(story.stageLabel)}</div>`}${button('nav:story',active.some(c=>c.ready)?'Report a completed contract →':'Open story & contracts →','text-button full-width')}</section>`;
}
export function renderStory(s){
 const state=G.storyState(s),catalog=Object.values(G.STORY_CONTRACTS),actions=G.availableStoryActions(s),active=state.active,available=state.available;
 return `<section class="panel story-intro"><div class="eyebrow">BELOW THE WATERLINE · A SLOWER STORY</div><h2>${esc(state.title)}</h2><p>Bracken Quay is still dry. The people keeping it that way are missing shifts, carrying injuries, and running out of spare parts. Earn their trust one job at a time.</p><p class="muted">Minor contracts establish what is happening and fund your preparations. Major contracts change the chapter. Accept a job, work toward its listed objectives, and report back for its reward.</p><div class="story-chapter-progress">${catalog.filter(c=>c.kind==='major').map(c=>{const v=G.contractStatus(s,c.id);return `<span class="${v.completed?'complete':v.active?'current':''}">${v.completed?'✓':(c.majorIndex+1)} ${esc(c.title)}</span>`;}).join('')}</div></section>${!safe(s)?'<div class="point-notice">Your current encounter or expedition is still active. You can review objectives here; return to town before accepting or reporting contracts.</div>':''}${actions.length?`<section class="panel story-contact"><div class="eyebrow">AT THE LOWER STAIR · MARA PELL</div><h3>A person, not a noticeboard.</h3><p>${esc(actions[0].text)}</p><div class="story-buttons">${actions.map(a=>`<div>${button('story-action:'+a.id,esc(a.label),'primary',!safe(s)||!a.enabled)}${a.reason?`<p class="story-hint">${esc(a.reason)}</p>`:''}</div>`).join('')}</div></section>`:''}<div class="story-columns"><section><div class="section-row"><h2>Accepted contracts</h2><small>${active.length} active</small></div>${active.length?active.map(c=>contractCard(s,c)).join(''):'<p class="empty-state">No active contract. Speak with Mara, then accept an available job.</p>'}</section><section><div class="section-row"><h2>Work you can take</h2><small>Clear goals · no timers</small></div>${available.length?available.map(c=>contractCard(s,c)).join(''):'<p class="empty-state">Finish the current story step to open the next job. Ordinary hunts remain available.</p>'}<details class="panel story-future"><summary>Later milestones & completed work</summary>${catalog.map(c=>{const v=G.contractStatus(s,c.id);if(v.active||v.available)return '';return `<div class="story-future-row"><strong>${v.completed?'✓ ':''}${esc(c.title)}</strong><span>${c.kind==='major'?'Major story milestone':'Minor contract'}</span>${v.completed?'<p>Completed. Rewards remain claimed.</p>':`<p>${v.requirements.filter(r=>!r.met).map(r=>esc(r.label)).join(' · ')}</p>`}</div>`;}).join('')}</details></section></div>`;
}
